180	     1	`timescale 1ns / 1ps
181	     2	`include "CtrlDefine.vh"
182	     3	
183	     4	module CtrlUnit(
184	     5	    input clk,
185	     6	    input rst,
186	     7	
187	     8	    input[31:0] PC,
188	     9	    input[31:0] inst,
189	    10	    input[31:0] imm,
190	    11	    
191	    12	    input ALU_done,
192	    13	    input MEM_done,
193	    14	    input MUL_done,
194	    15	    input DIV_done,
195	    16	    input JUMP_done,
196	    17	    input is_jump,
197	    18	
198	    19	    // IF
199	    20	    output IS_en,
200	    21	
201	    22	    // IS
202	    23	    output[2:0] ImmSel,
203	    24	
204	    25	    // RO/FU
205	    26	    output reg ALU_en, MEM_en, MUL_en, DIV_en, JUMP_en,
206	    27	    output reg[31:0] PC_ctrl,
207	    28	    output reg[31:0] imm_ctrl,
208	    29	    output reg[4:0] rs1_ctrl, rs2_ctrl, 
209	    30	    
210	    31	    // FU
211	    32	    output reg[4:0] JUMP_op,
212	    33	    output reg[3:0] ALU_op,
213	    34	    output reg ALU_use_PC,
214	    35	    output reg ALU_use_imm,
215	    36	    output reg MEM_we,
216	    37	    output reg[2:0] MEM_bhw,
217	    38	    output reg[2:0] MUL_op,
218	    39	    output reg[1:0] DIV_op,
219	    40	    
220	    41	    // WB
221	    42	    output reg[2:0] write_sel,
222	    43	    output reg reg_write,
223	    44	    output reg[4:0] rd_ctrl
224	    45	);
225	    46	    // used in for loop
226	    47	    integer i;
227	    48	
228	    49	    // Function Unit Status
229	    50	    // fields of FUS are defined at CtrlDefine.vh
230	    51	    reg[31:0] FUS[1:5];
231	    52	    reg[31:0] IMM[1:5];
232	    53	
233	    54	    // Register Status
234	    55	    // records which FU will write corresponding reg at WB
235	    56	    reg[2:0] RRS[0:31];
236	    57	
237	    58	    // sometimes an instruction needs PC to execute
238	    59	    // pc record
239	    60	    reg[31:0] PCR[1:5];
240	    61	
241	    62	    wire RO_en;
242	    63	    wire normal_stall;
243	    64	    reg ctrl_stall = 0, IS_flush = 0;
244	    65	
245	    66	    // a jump (JAL/JALR/BXX) instr has issued,
246	    67	    // stop issuing until result is known
247	    68	    wire jump_stall;
248	    69	
249	    70	    // instruction field
250	    71	    wire[6:0] funct7 = inst[31:25];
251	    72	    wire[2:0] funct3 = inst[14:12];
252	    73	    wire[6:0] opcode = inst[6:0];
253	    74	    wire[4:0] rd = inst[11:7];
254	    75	    wire[4:0] rs1 = inst[19:15];
255	    76	    wire[4:0] rs2 = inst[24:20];
256	    77	
257	    78	    // type specification
258	    79	    wire Rop = opcode == 7'b0110011;
259	    80	    wire Iop = opcode == 7'b0010011;
260	    81	    wire Bop = opcode == 7'b1100011;
261	    82	    wire Lop = opcode == 7'b0000011;
262	    83	    wire Sop = opcode == 7'b0100011;
263	    84	
264	    85	    wire funct7_0  = funct7 == 7'h0;
265	    86	    wire funct7_1  = funct7 == 7'h1;
266	    87	    wire funct7_32 = funct7 == 7'h20;
267	    88	
268	    89	    wire funct3_0 = funct3 == 3'h0;
269	    90	    wire funct3_1 = funct3 == 3'h1;
270	    91	    wire funct3_2 = funct3 == 3'h2;
271	    92	    wire funct3_3 = funct3 == 3'h3;
272	    93	    wire funct3_4 = funct3 == 3'h4;
273	    94	    wire funct3_5 = funct3 == 3'h5;
274	    95	    wire funct3_6 = funct3 == 3'h6;
275	    96	    wire funct3_7 = funct3 == 3'h7;
276	    97	
277	    98	    wire ADD  = Rop & funct3_0 & funct7_0;
278	    99	    wire SUB  = Rop & funct3_0 & funct7_32;
279	   100	    wire SLL  = Rop & funct3_1 & funct7_0;
280	   101	    wire SLT  = Rop & funct3_2 & funct7_0;
281	   102	    wire SLTU = Rop & funct3_3 & funct7_0;
282	   103	    wire XOR  = Rop & funct3_4 & funct7_0;
283	   104	    wire SRL  = Rop & funct3_5 & funct7_0;
284	   105	    wire SRA  = Rop & funct3_5 & funct7_32;
285	   106	    wire OR   = Rop & funct3_6 & funct7_0;
286	   107	    wire AND  = Rop & funct3_7 & funct7_0;
287	   108	
288	   109	    wire MUL    = Rop & funct3_0 & funct7_1;
289	   110	    wire MULH   = Rop & funct3_1 & funct7_1;
290	   111	    wire MULHSU = Rop & funct3_2 & funct7_1;
291	   112	    wire MULHU  = Rop & funct3_3 & funct7_1;
292	   113	    wire DIV    = Rop & funct3_4 & funct7_1;
293	   114	    wire DIVU   = Rop & funct3_5 & funct7_1;
294	   115	    wire REM    = Rop & funct3_6 & funct7_1;
295	   116	    wire REMU    = Rop & funct3_7 & funct7_1;
296	   117	
297	   118	    wire ADDI  = Iop & funct3_0;	
298	   119	    wire SLTI  = Iop & funct3_2;
299	   120	    wire SLTIU = Iop & funct3_3;
300	   121	    wire XORI  = Iop & funct3_4;
301	   122	    wire ORI   = Iop & funct3_6;
302	   123	    wire ANDI  = Iop & funct3_7;
303	   124	    wire SLLI  = Iop & funct3_1 & funct7_0;
304	   125	    wire SRLI  = Iop & funct3_5 & funct7_0;
305	   126	    wire SRAI  = Iop & funct3_5 & funct7_32;
306	   127	
307	   128	    wire BEQ = Bop & funct3_0;
308	   129	    wire BNE = Bop & funct3_1;
309	   130	    wire BLT = Bop & funct3_4;
310	   131	    wire BGE = Bop & funct3_5;
311	   132	    wire BLTU = Bop & funct3_6;
312	   133	    wire BGEU = Bop & funct3_7;
313	   134	
314	   135	    wire LB =  Lop & funct3_0;
315	   136	    wire LH =  Lop & funct3_1;
316	   137	    wire LW =  Lop & funct3_2;
317	   138	    wire LBU = Lop & funct3_4;
318	   139	    wire LHU = Lop & funct3_5;
319	   140	
320	   141	    wire SB = Sop & funct3_0;
321	   142	    wire SH = Sop & funct3_1;
322	   143	    wire SW = Sop & funct3_2;
323	   144	
324	   145	    wire LUI   = opcode == 7'b0110111;
325	   146	    wire AUIPC = opcode == 7'b0010111;
326	   147	
327	   148	    wire JAL  =  opcode == 7'b1101111;
328	   149	    wire JALR = (opcode == 7'b1100111) && funct3_0;
329	   150	
330	   151	    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU 
331	   152	        | MUL | MULH | MULHSU | MULHU | DIV | DIVU | REM | REMU;
332	   153	    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
333	   154	    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
334	   155	    wire L_valid = LW | LH | LB | LHU | LBU;
335	   156	    wire S_valid = SW | SH | SB;
336	   157	
337	   158	    // function unit specification
338	   159	    wire use_ALU = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU
339	   160	        | I_valid | LUI | AUIPC;
340	   161	    wire use_MEM = L_valid | S_valid;
341	   162	    wire use_MUL = MUL | MULH | MULHSU | MULHU;
342	   163	    wire use_DIV = DIV | DIVU | REM | REMU;
343	   164	    wire use_JUMP = B_valid | JAL | JALR;
344	   165	
345	   166	    wire[2:0] use_FU = {3{use_ALU}}  & `FU_ALU  |
346	   167	                       {3{use_MEM}}  & `FU_MEM  |
347	   168	                       {3{use_MUL}}  & `FU_MUL  |
348	   169	                       {3{use_DIV}}  & `FU_DIV  |
349	   170	                       {3{use_JUMP}} & `FU_JUMP ;
350	   171	
351	   172	    // registers to be used
352	   173	    wire[4:0] dst = {5{R_valid | I_valid | L_valid | LUI | AUIPC | JAL | JALR}} & rd;
353	   174	    wire[4:0] src1 = {5{R_valid | I_valid | S_valid | L_valid | B_valid | JALR}} & rs1;
354	   175	    wire[4:0] src2 = {5{R_valid | S_valid | B_valid}} & rs2;
355	   176	    // initial values of some FUS fields
356	   177	    wire[2:0] fu1 = RRS[src1];
357	   178	    wire[2:0] fu2 = RRS[src2];
358	   179	    wire rdy1 = ~|fu1;
359	   180	    wire rdy2 = ~|fu2;
360	   181	
361	   182	    // normal stall: structural hazard or WAW
362	   183	    assign normal_stall = ...;           //fill sth. here
363	   184	
364	   185	    assign IS_en = IS_flush | ~normal_stall & ~ctrl_stall;
365	   186	    assign RO_en = ~IS_flush & ~normal_stall & ~ctrl_stall;
366	   187	
367	   188	    always @ (posedge clk or posedge rst) begin
368	   189	        if (rst) begin
369	   190	            ctrl_stall <= 0;
370	   191	        end
371	   192	        else begin
372	   193	            // IS
373	   194	            if (RO_en & (use_FU == `FU_JUMP)) begin
374	   195	                ctrl_stall <= 1;
375	   196	            end
376	   197	            else if (JUMP_done) begin
377	   198	                ctrl_stall <= 0;
378	   199	            end
379	   200	        end
380	   201	    end
381	   202	
382	   203	    always @ (posedge clk or posedge rst) begin
383	   204	        if (rst) begin
384	   205	            IS_flush <= 0;
385	   206	        end
386	   207	        else if (JUMP_done & is_jump) begin
387	   208	            IS_flush <= 1;
388	   209	        end
389	   210	        else begin
390	   211	            IS_flush <= 0;
391	   212	        end
392	   213	    end
393	   214	
394	   215	    assign jump_stall = FUS[`FU_JUMP][`BUSY] & (~JUMP_done);
395	   216	
