     1	`timescale 1ns / 1ps
     2	
     3	module RAM_B(
     4	    input [31:0] addra,
     5	    input clka,      // normal clock
     6	    input[31:0] dina,
     7	    input wea, 
     8	    output[31:0] douta,
     9	    output [7:0] sim_uart_char_out,
    10	    output sim_uart_char_valid,
    11	    input[2:0] mem_u_b_h_w
    12	);
    13	    localparam SIZE = 256;
    14	    localparam ADDR_LINE = $clog2(SIZE);
    15	    localparam SIM_UART_ADDR = 32'h10000000;
    16	
    17	    reg[7:0] data[0:SIZE-1];
    18	
    19	    initial	begin
    20	        $readmemh("ram.mem", data);
    21	    end
    22	
    23	    // 地址译码：数据存储器只占用低地址空间，取地址低 ADDR_LINE 位
    24	    wire[ADDR_LINE-1:0] addr = addra[ADDR_LINE-1:0];
    25	    wire is_uart   = (addra == SIM_UART_ADDR);
    26	    wire word_op   = mem_u_b_h_w[1];
    27	    wire half_op   = mem_u_b_h_w[0];
    28	    wire unsigned_op = mem_u_b_h_w[2];
    29	
    30	    // 实现：按字节写入
    31	    // Write byte/halfword/word based on mem_u_b_h_w control signals.
    32	    // mem_u_b_h_w[1]=1 means word, mem_u_b_h_w[0]=1 means halfword, otherwise byte.
    33	    // Only write when wea is asserted. SIM_UART_ADDR writes should be excluded.
    34	    always @(posedge clka) begin
    35	        if (wea & ~is_uart) begin
    36	            if (word_op) begin
    37	                data[addr]                          <= dina[7:0];
    38	                data[(addr + 1) % SIZE]             <= dina[15:8];
    39	                data[(addr + 2) % SIZE]             <= dina[23:16];
    40	                data[(addr + 3) % SIZE]             <= dina[31:24];
    41	            end
    42	            else if (half_op) begin
    43	                data[addr]                          <= dina[7:0];
    44	                data[(addr + 1) % SIZE]             <= dina[15:8];
    45	            end
    46	            else begin
    47	                data[addr]                          <= dina[7:0];
    48	            end
    49	        end
    50	    end
    51	
    52	    // 实现：按字节读出并做符号/零扩展
    53	    // Read byte/halfword/word based on mem_u_b_h_w.
    54	    // mem_u_b_h_w[2]=1 means unsigned (zero-extend), otherwise sign-extend.
    55	    // Return 0 if address is SIM_UART_ADDR.
    56	    wire[31:0] rdata_w = {data[(addr + 3) % SIZE], data[(addr + 2) % SIZE],
    57	                          data[(addr + 1) % SIZE], data[addr]};
    58	    wire[15:0] rdata_h = {data[(addr + 1) % SIZE], data[addr]};
    59	    wire[7:0]  rdata_b = data[addr];
    60	
    61	    assign douta = is_uart ? 32'b0 :
    62	                   word_op ? rdata_w :
    63	                   half_op ? (unsigned_op ? {16'b0, rdata_h} : {{16{rdata_h[15]}}, rdata_h}) :
    64	                             (unsigned_op ? {24'b0, rdata_b} : {{24{rdata_b[7]}},  rdata_b}) ;
    65	
    66	    // 实现：串口模拟输出
    67	    // Detect writes to SIM_UART_ADDR, latch character data, and output via sim_uart_char_out.
    68	    reg[7:0] uart_char_reg;
    69	    reg      uart_valid_reg;
    70	
    71	    initial begin
    72	        uart_char_reg  = 8'b0;
    73	        uart_valid_reg = 1'b0;
    74	    end
    75	
    76	    always @(posedge clka) begin
    77	        if (wea & is_uart) begin
    78	            uart_char_reg  <= dina[7:0];
    79	            uart_valid_reg <= 1'b1;
    80	            // 仿真时直接把字符打印到控制台
    81	            // synthesis translate_off
    82	            $write("%c", dina[7:0]);
    83	            // synthesis translate_on
    84	        end
    85	        else begin
    86	            uart_valid_reg <= 1'b0;
    87	        end
    88	    end
    89	
    90	    assign sim_uart_char_valid = uart_valid_reg;
    91	    assign sim_uart_char_out   = uart_char_reg;
    92	endmodule=== lab4 RAM_B ===
